import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BCectEOt.js";const u=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/faq/"}],["meta",{"property":"og:title","content":"Frequently asked questions | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md"}'),n={name:"faq/index.md"};function i(s,e,d,l,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><h2 id="which-games-are-supported" tabindex="-1">Which games are supported? <a class="header-anchor" href="#which-games-are-supported" aria-label="Permalink to &quot;Which games are supported?&quot;">​</a></h2><p>Sapphire Star Codex covers <strong>Monster Hunter Wilds</strong>, <strong>Rise + Sunbreak</strong>, and <strong>World + Iceborne</strong>. Each game has its own data. Switch games from Home to browse the right monsters, equipment, quests and mechanics.</p><h2 id="can-i-download-it-yet" tabindex="-1">Can I download it yet? <a class="header-anchor" href="#can-i-download-it-yet" aria-label="Permalink to &quot;Can I download it yet?&quot;">​</a></h2><p>Public App Store, Google Play and AppGallery listings are not available yet. All three native apps are in development. The <a href="./../#download">download section</a> will show verified store links once they are live.</p><h2 id="does-it-work-offline" tabindex="-1">Does it work offline? <a class="header-anchor" href="#does-it-work-offline" aria-label="Permalink to &quot;Does it work offline?&quot;">​</a></h2><p>Core dex data is bundled with the app. Browsing, search, favorites and armor build tools work locally. Opening an external resource or downloading a future app update needs a connection.</p><h2 id="what-does-the-armor-builder-do" tabindex="-1">What does the armor builder do? <a class="header-anchor" href="#what-does-the-armor-builder-do" aria-label="Permalink to &quot;What does the armor builder do?&quot;">​</a></h2><p>Choose required skills and levels, fix equipment, exclude pieces, and search for compatible sets. You can limit the search to owned decorations. Rise also supports owned talismans and Qurious armor. Results depend on the selected game&#39;s data and your constraints; the builder is not a damage calculator.</p><h2 id="which-languages-are-included" tabindex="-1">Which languages are included? <a class="header-anchor" href="#which-languages-are-included" aria-label="Permalink to &quot;Which languages are included?&quot;">​</a></h2><p>English, Japanese, Simplified Chinese and Traditional Chinese. Missing individual translations fall back to English. Website screenshots use the language selected on this site.</p><h2 id="is-this-an-official-capcom-app" tabindex="-1">Is this an official Capcom app? <a class="header-anchor" href="#is-this-an-official-capcom-app" aria-label="Permalink to &quot;Is this an official Capcom app?&quot;">​</a></h2><p>No. This is the project&#39;s own website for an independent, non-commercial fan companion. It is not affiliated with or endorsed by CAPCOM. Monster Hunter, game artwork and game data belong to CAPCOM Co., Ltd.</p><h2 id="how-can-i-help" tabindex="-1">How can I help? <a class="header-anchor" href="#how-can-i-help" aria-label="Permalink to &quot;How can I help?&quot;">​</a></h2><p>See <a href="./../others/">About &amp; support</a> for feedback guidance and attribution. Useful corrections include the game, entity name, current value and a reproducible source.</p>',15)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
